package android.content;
public final class ContentValues {private final java.util.Map<String,Object> data=new java.util.HashMap<>();public ContentValues(){}public ContentValues(ContentValues other){data.putAll(other.data);}public void put(String key,String value){data.put(key,value);}public void put(String key,Long value){data.put(key,value);}public void put(String key,Integer value){data.put(key,value);}public void putNull(String key){data.put(key,null);}public Object get(String key){return data.get(key);}public String getAsString(String key){Object v=data.get(key);return v==null?null:v.toString();}public Long getAsLong(String key){String v=getAsString(key);return v==null?null:Long.valueOf(v);}public Integer getAsInteger(String key){String v=getAsString(key);return v==null?null:Integer.valueOf(v);}public java.util.Set<String> keySet(){return data.keySet();}}
